static inline float relu(float x) { return (x > 0.0f) ? x : 0.0f; }

static float ann_predict(float *input) {
    float h1[128] = {0};
    float h2[128] = {0};
    float out = 0.0f;

    float norm_input[80];
    for (int i = 0; i < 80; i++) {
        norm_input[i] = (input[i] - scaler_mean[i]) / scaler_scale[i];
    }

    for (int i = 0; i < 128; i++) {
        float sum = b0[i];
        for (int j = 0; j < 80; j++) {
            sum += W0[i * 80 + j] * norm_input[j];
        }
        h1[i] = relu(sum);
    }

    for (int i = 0; i < 128; i++) {
        float sum = b1[i];
        for (int j = 0; j < 128; j++) {
            sum += W1[i * 128 + j] * h1[j];
        }
        h2[i] = relu(sum);
    }

    out = b2[0];
    for (int i = 0; i < 128; i++) {
        out += W2[i] * h2[i];
    }

    if (out > 80.0f) out = 80.0f;
    if (out < -10.0f) out = -10.0f;
    return out;
}

